referenceSolutions.javascript:
function roundDeskThresholdFile(readings, k) {
  const a=readings; let out=[];
  const remaining=[...a],queue=[];out=Array(a.length).fill(0);for(let i=0;i<a.length;i++)if(a[i]>0)queue.push(i);let time=0;for(let head=0,tail=queue.length;head<tail;head++){const i=queue[head%a.length],served=Math.min(k,remaining[i]);remaining[i]-=served;time+=served;if(remaining[i])queue[tail++%a.length]=i;else out[i]=time;}
  return out.filter(x=>x>=k).length;
}

